"""Dense vector evaluation of NetNomos AST formulas over numpy columns.

The supplied ``netnomos.theory`` module evaluates formulas against a pandas
frame.  The finite telemetry protocol needs the same semantics over the
declared Cartesian universe of windows, which is produced here as dense
boolean vectors so that discovery and decoding stay exact and cheap.
"""
from __future__ import annotations

from typing import Any, Mapping, Sequence

import numpy as np

from netnomos.ast import (
    BinaryTerm,
    BoolAnd,
    BoolConst,
    BoolNot,
    BoolOr,
    Compare,
    Constant,
    Exists,
    Formula,
    ForAll,
    FuncCall,
    Implies,
    IndexedRef,
    SymbolRef,
    Term,
)


def resolve_indexed_column(term: IndexedRef, families: Mapping[str, Sequence[str]], env: Mapping[str, Any]) -> str:
    """Column name selected by an indexed reference inside a quantifier."""
    index = env.get(term.index, term.index)
    if isinstance(index, str) and index.isdigit():
        index = int(index)
    if not isinstance(index, int):
        raise ValueError(f"Indexed reference requires an integer index: {term.base}[{term.index}]")
    if term.base not in families:
        raise KeyError(f"Unknown context family: {term.base}")
    return families[term.base][index]


def evaluate_term_vectors(
    term: Term,
    columns: Mapping[str, np.ndarray],
    length: int,
    families: Mapping[str, Sequence[str]] | None = None,
    env: Mapping[str, Any] | None = None,
) -> Any:
    """Evaluate one AST term into a numpy vector (or a plain scalar)."""
    families = families or {}
    env = env or {}
    if isinstance(term, Constant):
        return term.value
    if isinstance(term, SymbolRef):
        return columns[term.name]
    if isinstance(term, IndexedRef):
        return columns[resolve_indexed_column(term, families, env)]
    if isinstance(term, BinaryTerm):
        left = evaluate_term_vectors(term.left, columns, length, families, env)
        right = evaluate_term_vectors(term.right, columns, length, families, env)
        if term.op == '+':
            return np.add(left, right)
        if term.op == '-':
            return np.subtract(left, right)
        if term.op == '*':
            return np.multiply(left, right)
        if term.op == '/':
            return np.divide(left, right)
        raise ValueError(f"Unsupported term op: {term.op}")
    if isinstance(term, FuncCall):
        args = [evaluate_term_vectors(arg, columns, length, families, env) for arg in term.args]
        name = term.name.lower()
        if name == 'sum':
            total = np.zeros(length, dtype=np.int64)
            for arg in args:
                total = total + arg
            return total
        if name == 'min':
            result = args[0]
            for arg in args[1:]:
                result = np.minimum(result, arg)
            return result
        if name == 'max':
            result = args[0]
            for arg in args[1:]:
                result = np.maximum(result, arg)
            return result
        if name == 'avg':
            total = np.zeros(length, dtype=np.int64)
            for arg in args:
                total = total + arg
            return total / len(args)
        if name == 'mod':
            if len(args) != 2:
                raise ValueError("MOD requires exactly two arguments")
            return np.mod(args[0], args[1])
        raise ValueError(f"Unsupported function: {term.name}")
    raise TypeError(f"Unsupported term node: {type(term)!r}")


def evaluate_formula_vectors(
    formula: Formula,
    columns: Mapping[str, np.ndarray],
    length: int,
    families: Mapping[str, Sequence[str]] | None = None,
    env: Mapping[str, Any] | None = None,
) -> np.ndarray:
    """Evaluate a formula into a dense boolean vector of the given length."""
    families = families or {}
    env = env or {}
    if isinstance(formula, BoolConst):
        return np.full(length, bool(formula.value), dtype=bool)
    if isinstance(formula, Compare):
        left = evaluate_term_vectors(formula.left, columns, length, families, env)
        right = evaluate_term_vectors(formula.right, columns, length, families, env)
        op = formula.op
        if op == '=':
            result = left == right
        elif op == '!=':
            result = left != right
        elif op == '<':
            result = left < right
        elif op == '<=':
            result = left <= right
        elif op == '>':
            result = left > right
        elif op == '>=':
            result = left >= right
        else:
            raise ValueError(f"Unsupported comparator: {op}")
        return np.asarray(result, dtype=bool)
    if isinstance(formula, BoolNot):
        return ~evaluate_formula_vectors(formula.value, columns, length, families, env)
    if isinstance(formula, BoolAnd):
        result = np.ones(length, dtype=bool)
        for child in formula.values:
            result &= evaluate_formula_vectors(child, columns, length, families, env)
        return result
    if isinstance(formula, BoolOr):
        result = np.zeros(length, dtype=bool)
        for child in formula.values:
            result |= evaluate_formula_vectors(child, columns, length, families, env)
        return result
    if isinstance(formula, Implies):
        left = evaluate_formula_vectors(formula.left, columns, length, families, env)
        right = evaluate_formula_vectors(formula.right, columns, length, families, env)
        return (~left) | right
    if isinstance(formula, ForAll):
        result = np.ones(length, dtype=bool)
        for value in formula.domain:
            body = evaluate_formula_vectors(
                formula.body, columns, length, families, {**env, formula.variable: value}
            )
            result &= body
        return result
    if isinstance(formula, Exists):
        result = np.zeros(length, dtype=bool)
        for value in formula.domain:
            body = evaluate_formula_vectors(
                formula.body, columns, length, families, {**env, formula.variable: value}
            )
            result |= body
        return result
    raise TypeError(f"Unsupported formula node: {type(formula)!r}")
