"""Independent brute-force reference implementation written straight from PROTOCOL.md."""
import itertools


def term_value(term, window, fields, slots):
    """window: dict (slot,name)->value"""
    if 'const' in term:
        return term['const']
    if 'sum' in term:
        return sum(window[tuple(r)] for r in term['sum'])
    if 'scale' in term:
        s = term['scale']
        r = tuple(term['ref'])
        return s * window[r]
    return window[tuple(term['ref'])]


def pred_value(pred, window, fields, slots):
    if pred['kind'] == 'cmp':
        left = term_value(pred['left'], window, fields, slots)
        right = term_value(pred['right'], window, fields, slots)
        op = pred['op']
        if op == 'eq': return left == right
        if op == 'ne': return left != right
        if op == 'lt': return left < right
        if op == 'le': return left <= right
        if op == 'gt': return left > right
        if op == 'ge': return left >= right
        raise ValueError(op)
    field = pred['field']
    op = pred['op']
    value = pred['value']
    cells = [window[(slot, field)] for slot in range(slots)]
    if pred['kind'] == 'any':
        return any(cmp(op, c, value) for c in cells)
    return all(cmp(op, c, value) for c in cells)


def cmp(op, left, right):
    if op == 'eq': return left == right
    if op == 'ne': return left != right
    if op == 'lt': return left < right
    if op == 'le': return left <= right
    if op == 'gt': return left > right
    if op == 'ge': return left >= right
    raise ValueError(op)


def universe_windows(job):
    """Yield (index, window dict) in lexicographic flattened-cell order."""
    fields = job['fields']
    slots = job['slots']
    cells = [(slot, f['name']) for slot in range(slots) for f in fields]
    choices = [f['domain'] for f in fields for _ in range(slots)]
    # choices must follow cell order (slot major, field order)
    choices = []
    for slot in range(slots):
        for f in fields:
            choices.append(f['domain'])
    idx = 0
    for combo in itertools.product(*choices):
        window = {cell: value for cell, value in zip(cells, combo)}
        yield idx, window
        idx += 1


def compile_job(job):
    fields = job['fields']
    slots = job['slots']
    preds = job['predicates']
    width = job['width']
    universe = list(universe_windows(job))
    upred = [[pred_value(p, w, fields, slots) for _, w in universe] for p in preds]
    train = []
    for window in job['train']:
        w = {}
        for slot, row in enumerate(window):
            for f, value in zip(fields, row):
                w[(slot, f['name'])] = value
        train.append(w)
    tpred = [[pred_value(p, w, fields, slots) for w in train] for p in preds]
    n = len(train)
    U = len(universe)

    rules = []
    npred = len(preds)
    for size in range(1, min(width, npred) + 1):
        for combo in itertools.combinations(range(npred), size):
            if not all(any(tpred[p][i] for p in combo) for i in range(n)):
                continue
            minimal = True
            for p in combo:
                others = [q for q in combo if q != p]
                if not any(all(not tpred[q][i] for q in others) for i in range(n)):
                    minimal = False
                    break
            if not minimal:
                continue
            ce = None
            for u, w in enumerate(universe):
                if all(not upred[p][u] for p in combo):
                    ce = u
                    break
            if ce is None:
                continue
            witnesses = []
            for p in combo:
                others = [q for q in combo if q != p]
                wit = None
                for i in range(n):
                    if tpred[p][i] and all(not tpred[q][i] for q in others):
                        wit = i
                        break
                witnesses.append(wit)
            rules.append({'clause': list(combo), 'witnesses': witnesses, 'counterexample': ce})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))

    approved = {tuple(sorted(c)) for c in job['approved']}
    active = [r['clause'] for r in rules if tuple(r['clause']) in approved]

    answers = []
    for query in job['queries']:
        fixed = {(tuple(b['ref']): b['value']) for b in query['fixed']}
        target = tuple(query['target'])
        prefix = query['prefix']
        count = 0
        witness = None
        tokens = []
        end = False
        for u, w in universe:
            ok = True
            for ref, value in fixed.items():
                if w[ref] != value:
                    ok = False
                    break
            if not ok:
                continue
            clause_ok = True
            for clause in active:
                if not any(upred[p][u] for p in clause):
                    clause_ok = False
                    break
            if not clause_ok:
                continue
            spelling = str(w[target])
            if not spelling.startswith(prefix):
                continue
            count += 1
            if witness is None:
                witness = u
            if len(spelling) == len(prefix):
                end = True
            else:
                if spelling[len(prefix)] not in tokens:
                    tokens.append(spelling[len(prefix)])
        tokens = sorted(tokens)
        if end:
            tokens.append('END')
        answers.append({'count': count, 'tokens': tokens, 'witness': witness})
    return {'rules': rules, 'active': active, 'answers': answers}
