        self.size = total
        flat = np.arange(total, dtype=np.int64)
        self.values: list[np.ndarray] = [None] * self.cell_count
        self.positions: list[np.ndarray] = [None] * self.cell_count
        self._prefix_cache: dict[tuple[str, str], np.ndarray] = {}
        self._spelling_cache: dict[str, list[str]] = {}
